/// Go `getNodeDataType`.
pub fn node_data_type(node: P<Node>) -> u32 {
    match node.kind() {
        Kind::Identifier
        | Kind::PrivateIdentifier
        | Kind::JsxText
        | Kind::JSDocText
        | Kind::JSDocLink
        | Kind::JSDocLinkPlain
        | Kind::JSDocLinkCode => NODE_DATA_TYPE_STRING,
        Kind::StringLiteral
        | Kind::NumericLiteral
        | Kind::BigIntLiteral
        | Kind::RegularExpressionLiteral
        | Kind::NoSubstitutionTemplateLiteral
        | Kind::TemplateHead
        | Kind::TemplateMiddle
        | Kind::TemplateTail
        | Kind::SourceFile => NODE_DATA_TYPE_EXTENDED_DATA,
        _ => NODE_DATA_TYPE_CHILDREN,
    }
}

